tests.code:
ARM MP+dmb+addr
"Reader has an address dependency between the two loads; writer is fenced.
 Forbidden by ARM (dependency preserved), allowed by bare Coherence (deps ignored)."
{ 0:r1=x; 0:r3=y; 1:r1=y; 1:r3=x; }
 P0           | P1            ;
 MOV r0,#1    | LDR r0,[r1]   ;
 STR r0,[r1]  | EOR r2,r0,r0  ;
 DMB          | LDR r4,[r3,r2];
 MOV r2,#1    |               ;
 STR r2,[r3]  |               ;
exists (1:r0=1 /\ 1:r4=0)

AArch64 WRC+addrs
"Same WRC+addrs in AArch64 syntax. Forbidden by ARMv8 (multi-copy atomic)."
{ 0:X1=x; 1:X1=x; 1:X3=y; 2:X1=y; 2:X3=x; }
 P0          | P1                  | P2                  ;
 MOV W0,#1   | LDR W0,[X1]         | LDR W0,[X1]         ;
 STR W0,[X1] | EOR W4,W0,W0        | EOR W4,W0,W0        ;
            | STR W0,[X3,W4,SXTW]  | LDR W2,[X3,W4,SXTW] ;
exists (1:X0=1 /\ 2:X0=1 /\ 2:X2=0)

ARM WRC+addrs
"Write-to-read causality with address dependencies. A non-multi-copy-atomic
 behaviour: allowed by ARMv7 (non-MCA), forbidden by ARMv8 (MCA).
 P0 writes x; P1 reads x then (addr-dep) writes y; P2 reads y then (addr-dep)
 reads x. Seeing P1:x=1, P2:y=1 but P2:x=0 means the two writes were not seen
 in the same order by everyone."
{ 0:r1=x; 1:r1=x; 1:r3=y; 2:r1=y; 2:r3=x; }
 P0          | P1            | P2            ;
 MOV r0,#1   | LDR r0,[r1]   | LDR r0,[r1]   ;
 STR r0,[r1] | EOR r2,r0,r0  | EOR r2,r0,r0  ;
            | STR r0,[r3,r2] | LDR r4,[r3,r2];
exists (1:r0=1 /\ 2:r0=1 /\ 2:r4=0)

C mp-rs-st-eadd-atomics
{ [x] = 0; [y] = 0;  }

P0 (int* x, int* y) {
  atomic_store_explicit(y, 1, memory_order_relaxed);
  atomic_store_explicit(x, 1, memory_order_release);
  atomic_store_explicit(x, 3, memory_order_relaxed);
}

P1 (int* x, int* y) {
  int a = atomic_load_explicit(x, memory_order_acquire);
  if (a > 1) {
    int b = atomic_load_explicit(y, memory_order_relaxed);
  }
}

P2 (int* x) {
  atomic_fetch_add_explicit(x, 1, memory_order_relaxed);
}

~exists((1:a=2 \/ 1:a=4) /\ 1:b=0)

C MP+block-relaxed
"CUDA message passing whose release/acquire are at cuda::thread_scope_block, with
 the producer and consumer in DIFFERENT thread blocks. The genuine CUDA source is:

   // producer, block 0
   x = 1;
   cuda::atomic_ref<int, cuda::thread_scope_block> f_ref(f);
   f_ref.store(1, cuda::memory_order_release);
   // consumer, block 1
   cuda::atomic_ref<int, cuda::thread_scope_block> f_ref(f);
   r0 = f_ref.load(cuda::memory_order_acquire);
   r1 = x;

 A block-scoped release/acquire orders only threads in the SAME block; across
 blocks it carries no happens-before, so it behaves exactly like
 memory_order_relaxed. We model that with relaxed atomics: the MP outcome herd7
 -c11 reports as Sometimes is the behaviour CUDA ALLOWS at block scope and flat C11
 FORBIDS (see MP+relacq.litmus). Promoting the scope to thread_scope_system
 recovers C11 and the outcome vanishes. CUDA's cuda::atomic is lowered to the PTX
 memory model (Lustig et al. 2019)."
{ int x=0; int f=0; }
P0 (atomic_int* x, atomic_int* f) {
  atomic_store_explicit(x,1,memory_order_relaxed);
  atomic_store_explicit(f,1,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_relaxed);
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
}
exists (1:r0=1 /\ 1:r1=0)

C MP+relacq
"Message passing with a release store and an acquire load. CUDA at
 cuda::thread_scope_system (and flat C11, where they coincide) FORBIDS reading the
 flag set but the data stale: the release/acquire pair orders the data write
 before the data read. herd7 -c11 => Never. The CUDA companion
 MP+block-relaxed.litmus narrows the same release/acquire to
 cuda::thread_scope_block with the two threads in different thread blocks, where it
 provides no synchronisation and the outcome reappears."
{ int x=0; int f=0; }
P0 (int* x, atomic_int* f) {
  *x = 1;
  atomic_store_explicit(f,1,memory_order_release);
}
P1 (int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_acquire);
  int r1 = *x;
}
exists (1:r0=1 /\ 1:r1=0)

C MP+relacq
"Message passing with a release store and an acquire load. C11's DRF-SC guarantee
 (a single, global scope) FORBIDS reading the flag set but the data stale: the
 synchronising release/acquire makes the program race-free and orders the data
 write before the data read. herd7 -c11 => Never. The HRF companion
 MP+scoped-relaxed.litmus has the producer and consumer synchronise at a COMMON
 sub-global scope they do not actually share, so under HRF the program contains a
 heterogeneous (scoped) data race and the outcome is admitted."
{ int x=0; int f=0; }
P0 (int* x, atomic_int* f) {
  *x = 1;
  atomic_store_explicit(f,1,memory_order_release);
}
P1 (int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_acquire);
  int r1 = *x;
}
exists (1:r0=1 /\ 1:r1=0)

C MP+scoped-relaxed
"Heterogeneous message passing under HRF. The producer and consumer each issue a
 release/acquire scoped to their OWN work-group, so they never synchronise at a
 shared scope. The genuine HRF-style source is:

   // producer, work-group A
   x = 1;
   atomic_store(&f, 1, release, scope(A));     // scope A only
   // consumer, work-group B
   r0 = atomic_load(&f, acquire, scope(B));    // scope B only
   r1 = x;

 HRF generalises DRF to a scope hierarchy: two synchronising operations order each
 other only when they name a COMMON scope. Here they do not, so x is touched by a
 heterogeneous (scoped) data race and HRF gives no SC-like guarantee — the MP
 outcome is allowed, exactly as for relaxed accesses (modelled here with relaxed
 atomics, herd7 -c11 => Sometimes). Flat C11 has a single global scope, so the
 same release/acquire DO synchronise and the outcome is forbidden (MP+relacq.litmus).
 Choosing a common scope (e.g. device) for both recovers the C11 guarantee."
{ int x=0; int f=0; }
P0 (atomic_int* x, atomic_int* f) {
  atomic_store_explicit(x,1,memory_order_relaxed);
  atomic_store_explicit(f,1,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_relaxed);
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
}
exists (1:r0=1 /\ 1:r1=0)

C MP+relacq
"Message passing with a release store and an acquire load. Flat C11 (and OpenCL
 at all-svm-devices scope, where the two coincide) FORBIDS reading the flag set
 but the data stale: the release/acquire pair establishes happens-before from the
 data write to the data read. herd7 -c11 => Never. The OpenCL companion
 MP+wg-relaxed.litmus narrows the same release/acquire to work_group scope across
 two work-groups, where it provides no synchronisation and the outcome reappears."
{ int x=0; int f=0; }
P0 (int* x, atomic_int* f) {
  *x = 1;
  atomic_store_explicit(f,1,memory_order_release);
}
P1 (int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_acquire);
  int r1 = *x;
}
exists (1:r0=1 /\ 1:r1=0)

C MP+wg-relaxed
"OpenCL message passing whose release/acquire are at memory_scope_work_group, with
 P0 and P1 in DIFFERENT work-groups. The genuine OpenCL source is:

   // P0, work-group A
   x = 1;
   atomic_store_explicit(&f, 1, memory_order_release, memory_scope_work_group);
   // P1, work-group B
   r0 = atomic_load_explicit(&f, memory_order_acquire, memory_scope_work_group);
   r1 = x;

 A work_group-scoped release/acquire synchronises only threads in the SAME
 work-group; across work-groups it carries no happens-before, so it behaves
 exactly like memory_order_relaxed. We model that here with relaxed atomics: the
 MP outcome herd7 -c11 reports as Sometimes is the behaviour OpenCL ALLOWS at
 work_group scope and flat C11 FORBIDS (see MP+relacq.litmus). Promoting the scope
 to memory_scope_all_svm_devices recovers C11 and the outcome vanishes."
{ int x=0; int f=0; }
P0 (atomic_int* x, atomic_int* f) {
  atomic_store_explicit(x,1,memory_order_relaxed);
  atomic_store_explicit(f,1,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_relaxed);
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
}
exists (1:r0=1 /\ 1:r1=0)

C MP+relacq
"Message passing with a release store and an acquire load -- the strongest shape
 CRC can express, since CRC's fragment is non-atomic + release/acquire +
 SC-fences and deliberately OMITS relaxed atomics (to sidestep thin-air). The
 release/acquire pair builds happens-before from the data write to the data read,
 so the stale-data outcome r0=1 /\ r1=0 is a coherence violation: CRC FORBIDS it,
 and so does flat C11 on this annotation. herd7 -c11 => Never. This is the CRC
 (stronger) side; the C11 (weaker) side is the relaxed companion MP+relaxed.litmus,
 which CRC cannot even write down and C11 allows."
{ int x=0; int f=0; }
P0 (int* x, atomic_int* f) {
  *x = 1;
  atomic_store_explicit(f,1,memory_order_release);
}
P1 (int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_acquire);
  int r1 = *x;
}
exists (1:r0=1 /\ 1:r1=0)

C MP+relaxed
"The same message-passing shape with RELAXED atomics on the flag. C11 ALLOWS the
 stale-data outcome r0=1 /\ r1=0: relaxed accesses carry no happens-before, so
 the writer's two stores and the reader's two loads may each be observed out of
 order. herd7 -c11 => Sometimes. CRC has NO relaxed accesses in its fragment, so
 this program lies outside CRC's language entirely -- equivalently, CRC's weakest
 atomic (release/acquire, MP+relacq.litmus) forbids the outcome. Thus C11 permits
 a behaviour CRC excludes: CRC is strictly stronger."
{ int x=0; int f=0; }
P0 (atomic_int* x, atomic_int* f) {
  atomic_store_explicit(x,1,memory_order_relaxed);
  atomic_store_explicit(f,1,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_relaxed);
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
}
exists (1:r0=1 /\ 1:r1=0)

C LB-oota
"Out-of-thin-air load buffering, CSRA's 'Example 2' shape: each thread stores 42
 ONLY in the branch taken when it has already read 42. P0 reads x; if it is 42 it
 writes y=42. P1 reads y; if it is 42 it writes x=42. The outcome r1=r2=42
 conjures 42 from a self-justifying cycle. C11 PERMITS it (its relaxed atomics do
 not forbid thin-air). CSRA FORBIDS it: because the write x=42 occurs in only one
 branch, CSRA's deordering cannot hoist it ahead of the read that guards it, so
 both reads can only see 0. CSRA's authors state it is a subset of C/C++11 by
 design ('the converse is not to be expected ... the point of our model is to
 exclude the thin-air executions that C/C++11 allows'), so C11 is strictly weaker
 and the only separating outcomes are OOTA ones. Verdicts CITED: herd7 cannot
 construct an OOTA execution, so it reports Never. See README."
{ int x=0; int y=0; }
P0 (atomic_int* x, atomic_int* y) {
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
  if (r1 == 42) atomic_store_explicit(y,42,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* y) {
  int r2 = atomic_load_explicit(y,memory_order_relaxed);
  if (r2 == 42) atomic_store_explicit(x,42,memory_order_relaxed);
}
exists (0:r1=42 /\ 1:r2=42)

C MP+inclusion-scopes
"Message passing where the producer releases at a LARGER scope and the consumer
 acquires at a SMALLER, included scope. Genuine scoped source:

   // producer
   x = 1;
   atomic_store(&f, 1, release, scope(device));        // device scope
   // consumer (a work-item inside that device)
   r0 = atomic_load(&f, acquire, scope(work_group));   // work_group scope
   r1 = x;

 HRF-direct requires the two scopes to MATCH EXACTLY to synchronise, and
 HRF-indirect only adds explicit transitive chains; neither recognises this
 device-release / work_group-acquire pair, so the program is a scoped race and the
 stale-data outcome (1:r0=1, 1:r1=0) is among the behaviours HRF admits. HRF-Relaxed
 / Scoped-C11 loosens matching to scope INCLUSION: the work_group is contained in
 the device, so the operations synchronise, the program is race-free, and an
 entire class of such inclusion-synchronising programs becomes well-defined that
 HRF did not admit. This is a model-DEFINITION difference (the matching rule), not
 a reordering herd7 can enumerate; herd7 has no scoped model. See README."
{ int x=0; int f=0; }
P0 (atomic_int* x, atomic_int* f) {
  atomic_store_explicit(x,1,memory_order_relaxed);
  atomic_store_explicit(f,1,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* f) {
  int r0 = atomic_load_explicit(f,memory_order_relaxed);
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
}
exists (1:r0=1 /\ 1:r1=0)

C LB-oota
"Out-of-thin-air load buffering. C11 relaxed atomics permit r1=r2=42 (the
 standard fails to forbid it). herd cannot *exhibit* OOTA executions, so it
 reports Never here; the permission is a property of the C11 axioms, not of
 what herd enumerates. See the README and the MoRDor (.lit) companion."
{ int x=0; int y=0; }
P0 (atomic_int* x, atomic_int* y) {
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
  atomic_store_explicit(y,r1,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* y) {
  int r2 = atomic_load_explicit(y,memory_order_relaxed);
  atomic_store_explicit(x,r2,memory_order_relaxed);
}
exists (0:r1=42 /\ 1:r2=42)

// Out-of-thin-air via value invention (cf. SMRD paper, "invent-in-the-load").
// The value 42 can only appear by speculating it into existence. C11's relaxed
// atomics permit (r0 = 42 && r1 = 42); MRD forbids it.
x := 0; y := 0;
{
  r0 := y;
  if (r0 != 42) {
    r0 := y;
    if (r0 != 42) {
      r0 := y;
      if (r0 != 42) { x := r0 }
      else { x := 42 }
    }
    else { x := 42 }
  }
  else { x := 42 }
}|||{
  r1 := x;
  if (r1 = 42) { y := 42 }
  else { y := r1 }
}
%% forbid (r0 = 42 && r1 = 42) []

// sMRD Example 1.1a (MoRDor-family syntax): load buffering with a FALSE
// dependency masked by undefined behaviour. The store to y is guarded by a
// computation (1/!r1) that is DEFINED only when r1 == 0; a compiler may assume
// well-definedness, constant-fold the store to y := 1, and break the
// read(x)->write(y) dependency. sMRD removes this semantically-false dependency
// and ALLOWS r0=r1=1; MRD, reasoning over concrete values, keeps the dependency
// and FORBIDS it. (Approximated here as a constant-folded store; the UB guard is
// what distinguishes the two models -- see README.)
x := 0; y := 0;
{
  r0 := x;
  y := 1            // sMRD: false dep removed (UB-justified); MRD: dep retained
}|||{
  r1 := y;
  x := r1
}
%% allow (r0 = 1 && r1 = 1) []     // sMRD verdict; MRD forbids this outcome

C LB+UB+data
"sMRD Example 1.1a: load buffering with a FALSE dependency masked by undefined
 behaviour. P0 reads x into r1, then stores to y the value 1/!r1 -- which is
 only DEFINED when r1==0 (otherwise it is a division by zero, i.e. UB). A
 compiler may therefore assume r1==0, constant-fold the store to a plain y=1,
 and break the read(x)->write(y) dependency. P1 reads y into r2 and stores r2 to
 x. The outcome r1=1 /\ r2=1 then becomes reachable.

 sMRD (Symbolic MRD) ALLOWS it: its symbolic dependency calculus reasons about
 undefined behaviour, sees the dependency is semantically false, removes it, and
 with no dp edge there is no (dp union rf) cycle to discard. This matches GCC/
 Clang, which perform exactly this optimisation. MRD (Modular Relaxed
 Dependencies) FORBIDS it: MRD computes dependencies over CONCRETE locations and
 values from program syntax, is UB-unaware, keeps the read(x)->write(y) data
 dependency, and so retains a (dp union rf) cycle and rules the outcome out.
 Neither model is in herd7; verdicts are CITED. See README."
{ int x=0; int y=0; }
P0 (atomic_int* x, atomic_int* y) {
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
  atomic_store_explicit(y, 1/(1-r1), memory_order_relaxed);   /* the paper's 1/!r1: defined only when r1==0 */
}
P1 (atomic_int* x, atomic_int* y) {
  int r2 = atomic_load_explicit(y,memory_order_relaxed);
  atomic_store_explicit(x, r2, memory_order_relaxed);
}
exists (0:r1=1 /\ 1:r2=1)

PPC MP+sync+addr
"Reader has an address dependency between the two loads; writer is fenced.
 Forbidden by POWER (dependency preserved), allowed by bare Coherence (deps ignored)."
{ 0:r2=x; 0:r4=y; 1:r2=y; 1:r5=x; }
 P0           | P1              ;
 li r1,1      | lwz r3,0(r2)    ;
 stw r1,0(r2) | xor r6,r3,r3    ;
 sync         | lwzx r7,r6,r5   ;
 li r3,1      |                 ;
 stw r3,0(r4) |                 ;
exists (1:r3=1 /\ 1:r7=0)

PPC MP+sync+po
"Writer fenced, reader does two plain loads => isolates load->load reordering.
 Allowed by POWER (loads reorder freely), forbidden by PSO (loads stay ordered).
 This is the only direction that separates them: see README -- on the standard
 litmus families PSO turns out to be *included in* POWER (PSO has no behaviour
 POWER lacks), so the 'incomparable' label is generous."
{ 0:r2=x; 0:r4=y; 1:r2=y; 1:r4=x; }
 P0           | P1            ;
 li r1,1      | lwz r1,0(r2)  ;
 stw r1,0(r2) | lwz r3,0(r4)  ;
 sync         |               ;
 li r3,1      |               ;
 stw r3,0(r4) |               ;
exists (1:r1=1 /\ 1:r3=0)

AArch64 LB
"Load buffering: load->store reordering. Forbidden under PSO (loads stay in order), allowed under RMO."
{ 0:X1=x; 0:X3=y; 1:X1=y; 1:X3=x; }
 P0           | P1           ;
 LDR W0,[X1]  | LDR W0,[X1]  ;
 MOV W2,#1    | MOV W2,#1    ;
 STR W2,[X3]  | STR W2,[X3]  ;
exists (0:X0=1 /\ 1:X0=1)

C Oscillating
"Lahav & Boker, TOPLAS 2022, Ex. 3.7 (Oscillating). One reader sees x go 1, then 2,
 then 1 again while two writers each write once. Under RA and SRA the reader's three
 reads are hb-ordered and mo totally orders the two writes, so returning to 1 after
 seeing 2 violates read-coherence: both FORBID it. WRA has no mo, and the two writes
 are hb|loc-unrelated, so nothing forbids the oscillation: WRA ALLOWS it."
{ }
P0 (atomic_int* x) { atomic_store_explicit(x,1,memory_order_release); }
P1 (atomic_int* x) {
  int r0 = atomic_load_explicit(x,memory_order_acquire);
  int r1 = atomic_load_explicit(x,memory_order_acquire);
  int r2 = atomic_load_explicit(x,memory_order_acquire);
}
P2 (atomic_int* x) { atomic_store_explicit(x,2,memory_order_release); }
exists (1:r0=1 /\ 1:r1=2 /\ 1:r2=1)

C SF
"Lahav & Boker, TOPLAS 2022, Ex. 3.7 (SF), the store-forwarding shape. A thread
 writes x=1, reads x=2 from the other thread, then reads x=1 again -- its own
 earlier write, now stale. RA and SRA FORBID it by read-coherence. WRA ALLOWS it,
 which is why WRA validates the store-forwarding optimisation that rewrites the
 second read to the constant 1: the paper notes that same rewrite is UNSOUND for
 RA and SRA, since it would yield this outcome even under SC."
{ }
P0 (atomic_int* x) {
  atomic_store_explicit(x,1,memory_order_release);
  int r0 = atomic_load_explicit(x,memory_order_acquire);
  int r1 = atomic_load_explicit(x,memory_order_acquire);
}
P1 (atomic_int* x) { atomic_store_explicit(x,2,memory_order_release); }
exists (0:r0=2 /\ 0:r1=1)

C WW
"Lahav & Boker, TOPLAS 2022, Ex. 3.7 (WW). Two threads each write x and then read
 it, and each reads the OTHER thread's value. Both writes are hb|loc-unrelated, so
 WRA's weak-read-coherence -- which uses hb|loc rather than mo to decide which of
 two writes to a location is the later -- has nothing to fire on, and WRA ALLOWS
 the outcome. RA and SRA order the two writes by mo, so whichever is mo-earlier is
 read by a thread aware of the mo-later one, violating read-coherence: both FORBID
 it. This is WRA failing SC-per-location on a single-location program."
{ }
P0 (atomic_int* x) {
  atomic_store_explicit(x,1,memory_order_release);
  int r0 = atomic_load_explicit(x,memory_order_acquire);
}
P1 (atomic_int* x) {
  atomic_store_explicit(x,2,memory_order_release);
  int r1 = atomic_load_explicit(x,memory_order_acquire);
}
exists (0:r0=2 /\ 1:r1=1)

C LB-relaxed
"Plain relaxed load buffering (no dependencies, no thin-air value invention). RC11
 enforces the no-thin-air axiom acyclic(po | rf), which forbids ALL load-buffering
 shapes, so RC11 reports Never. C++20 did NOT adopt that axiom (P0668 fixed seq_cst
 but deliberately left thin-air unresolved), so C++20 -- exactly like C11/C++17 --
 permits this LB. The C++20 side is modelled with herd7's original C11 model
 (c11_orig.cat), whose relaxed/thin-air fragment C++20 leaves unchanged => Sometimes.
   herd7 -model rc11.cat     => Never      (RC11 forbids)
   herd7 -model c11_orig.cat => Sometimes  (C++20, via the unchanged C11 fragment)"
{ int x=0; int y=0; }
P0 (atomic_int* x, atomic_int* y) {
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
  atomic_store_explicit(y,1,memory_order_relaxed);
}
P1 (atomic_int* x, atomic_int* y) {
  int r2 = atomic_load_explicit(y,memory_order_relaxed);
  atomic_store_explicit(x,1,memory_order_relaxed);
}
exists (0:r1=1 /\ 1:r2=1)

C IRIW+scfences
{ int x=0; int y=0; }
P0 (atomic_int* x) { atomic_store_explicit(x,1,memory_order_relaxed); }
P1 (atomic_int* y) { atomic_store_explicit(y,1,memory_order_relaxed); }
P2 (atomic_int* x, atomic_int* y) {
  int r1 = atomic_load_explicit(x,memory_order_relaxed);
  atomic_thread_fence(memory_order_seq_cst);
  int r2 = atomic_load_explicit(y,memory_order_relaxed);
}
P3 (atomic_int* x, atomic_int* y) {
  int r3 = atomic_load_explicit(y,memory_order_relaxed);
  atomic_thread_fence(memory_order_seq_cst);
  int r4 = atomic_load_explicit(x,memory_order_relaxed);
}
exists (2:r1=1 /\ 2:r2=0 /\ 3:r3=1 /\ 3:r4=0)

