// Zoo edge: IMM -> ARMv8 (compilation).
// The assume records the mapping premise that an RMW's read and write are
// ordered in mo (atomicity), which holds of any well-formed target execution.
include "../../kat/imm.kat"
include "../../kat/arm8.kat"

assume rf;rmw <= mo

assert imm::psc <= arm8::ob*

// Zoo edge: IMM -> x86-TSO (compilation).
// Soundness of the IMM-to-x86 mapping: IMM's global ordering constraint is
// implied by TSO's, so no compiled execution breaks the source semantics.
include "../../kat/imm.kat"
include "../../kat/tso.kat"

assert imm::psc <= tso::tso*
